def has_cycle_of_length(edges, n, max_len):
    """Check if graph has any cycle of length <= max_len"""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: (None, 0)}  # vertex -> (parent, distance)
        queue = [start]
        idx = 0
