            for v in adj[u]:
                if v not in visited:
                    visited[v] = (u, dist + 1)
                    queue.append(v)
                elif v != visited[u][0]:  # Found a cycle
                    cycle_len = dist + 1 + visited[v][1]
                    if cycle_len <= max_len:
                        return True
    return False

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
