from pysat.solvers import Glucose3
from pysat.card import CardEnc
from itertools import combinations

n = 14
target_edges = 19

edges_list = list(combinations(range(n), 2))
num_edges = len(edges_list)

def edge_var(i, j):
    idx = edges_list.index((i, j)) if i < j else edges_list.index((j, i))
    return idx + 1

solver = Glucose3()

# At least 19 edges
at_least_clauses = CardEnc.atleast(lits=list(range(1, num_edges + 1)), bound=target_edges)
for clause in at_least_clauses.clauses:
    solver.add_clause(clause)

# No cycles of length 3, 4, 5, 6
cycle_count = 0
for length in [3, 4, 5, 6]:
    for vertices in combinations(range(n), length):
        verts = list(vertices)
        from itertools import permutations
        for perm in permutations(verts[1:]):
            cycle = [verts[0]] + list(perm)
            clause = []
            for i in range(len(cycle)):
                u, v = cycle[i], cycle[(i+1) % len(cycle)]
                if u > v:
                    u, v = v, u
                var = edge_var(u, v)
                clause.append(-var)
            solver.add_clause(clause)
            cycle_count += 1

print(f"Added {cycle_count} cycle constraints")

# 4-colorable
color_vars = {}
for v in range(n):
    for k in range(4):
        color_vars[(v, k)] = num_edges + 1 + v * 4 + k

for v in range(n):
    solver.add_clause([color_vars[(v, k)] for k in range(4)])
    for k1 in range(4):
        for k2 in range(k1+1, 4):
            solver.add_clause([-color_vars[(v, k1)], -color_vars[(v, k2)]])

for u, v in edges_list:
    var = edge_var(u, v)
    for k in range(4):
        solver.add_clause([-var, -color_vars[(u, k)], -color_vars[(v, k)]])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    print("SAT!")
    selected_edges = []
    for idx, (u, v) in enumerate(edges_list):
        if model[idx] > 0:
            selected_edges.append((u, v))
    print(f"Selected edges: {len(selected_edges)}")
    print(selected_edges)
else:
    print("UNSAT")
